#!/bin/bash\n\n# Configuration Validation Script for AgentScan\n# Validates environment-specific configuration files and secrets\n\nset -euo pipefail\n\n# Script configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$(dirname \"$SCRIPT_DIR\")\")\"  # Go up two levels\nDEPLOYMENT_DIR=\"$PROJECT_ROOT/deployment\"\nENVIRONMENTS_DIR=\"$DEPLOYMENT_DIR/environments\"\n\n# Default configuration\nENVIRONMENT=\"production\"\nVERBOSE=false\nFIX_ISSUES=false\nCHECK_SECRETS=true\nCHECK_CONNECTIVITY=true\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog_info() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nlog_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nlog_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nlog_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_verbose() {\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo -e \"${BLUE}[VERBOSE]${NC} $1\"\n    fi\n}\n\n# Function to show help\nshow_help() {\n    cat << EOF\nAgentScan Configuration Validation Script\n\nUsage: $0 [OPTIONS]\n\nOptions:\n    --environment ENV       Environment to validate (default: production)\n    --verbose              Enable verbose logging\n    --fix                  Attempt to fix issues automatically\n    --skip-secrets         Skip secret validation\n    --skip-connectivity    Skip connectivity checks\n    --help                 Show this help message\n\nExamples:\n    $0 --environment production --verbose\n    $0 --environment staging --fix\n    $0 --skip-secrets --skip-connectivity\n\nEOF\n}\n\n# Function to validate YAML syntax\nvalidate_yaml_syntax() {\n    local file=\"$1\"\n    \n    log_verbose \"Validating YAML syntax: $file\"\n    \n    if ! command -v yq &> /dev/null; then\n        if command -v python3 &> /dev/null; then\n            # Use Python as fallback\n            if ! python3 -c \"import yaml; yaml.safe_load(open('$file'))\" 2>/dev/null; then\n                log_error \"Invalid YAML syntax in: $file\"\n                return 1\n            fi\n        else\n            log_warning \"Cannot validate YAML syntax (yq and python3 not available): $file\"\n            return 0\n        fi\n    else\n        if ! yq eval '.' \"$file\" >/dev/null 2>&1; then\n            log_error \"Invalid YAML syntax in: $file\"\n            return 1\n        fi\n    fi\n    \n    log_verbose \"YAML syntax valid: $file\"\n    return 0\n}\n\n# Function to validate configuration structure\nvalidate_config_structure() {\n    local config_file=\"$1\"\n    \n    log_info \"Validating configuration structure: $config_file\"\n    \n    if [[ ! -f \"$config_file\" ]]; then\n        log_error \"Configuration file not found: $config_file\"\n        return 1\n    fi\n    \n    # Validate YAML syntax first\n    if ! validate_yaml_syntax \"$config_file\"; then\n        return 1\n    fi\n    \n    # Check required sections\n    local required_sections=(\n        \"app\"\n        \"server\"\n        \"database\"\n        \"redis\"\n        \"supabase\"\n        \"security\"\n        \"agents\"\n        \"monitoring\"\n    )\n    \n    local missing_sections=()\n    \n    for section in \"${required_sections[@]}\"; do\n        if command -v yq &> /dev/null; then\n            if ! yq eval \"has(\\\"$section\\\")\" \"$config_file\" | grep -q \"true\"; then\n                missing_sections+=(\"$section\")\n            else\n                log_verbose \"Found required section: $section\"\n            fi\n        else\n            # Basic grep check as fallback\n            if ! grep -q \"^$section:\" \"$config_file\"; then\n                missing_sections+=(\"$section\")\n            else\n                log_verbose \"Found required section: $section\"\n            fi\n        fi\n    done\n    \n    if [[ ${#missing_sections[@]} -gt 0 ]]; then\n        log_error \"Missing required configuration sections:\"\n        printf '  %s\\n' \"${missing_sections[@]}\"\n        return 1\n    fi\n    \n    log_success \"Configuration structure validation passed\"\n    return 0\n}\n\n# Function to validate environment variables\nvalidate_environment_variables() {\n    local config_file=\"$1\"\n    \n    log_info \"Validating environment variable references...\"\n    \n    # Extract environment variable references from config\n    local env_vars=()\n    if command -v grep &> /dev/null; then\n        # Find ${VAR} patterns\n        mapfile -t env_vars < <(grep -oE '\\$\\{[A-Z_][A-Z0-9_]*\\}' \"$config_file\" | sort -u | sed 's/\\${\\(.*\\)}/\\1/')\n    fi\n    \n    local missing_vars=()\n    local optional_vars=()\n    \n    # Define required vs optional variables\n    local required_vars=(\n        \"DB_HOST\"\n        \"DB_NAME\"\n        \"DB_USER\"\n        \"DB_PASSWORD\"\n        \"REDIS_HOST\"\n        \"SUPABASE_URL\"\n        \"SUPABASE_ANON_KEY\"\n        \"JWT_SECRET\"\n    )\n    \n    local optional_vars_list=(\n        \"REDIS_PASSWORD\"\n        \"GITHUB_CLIENT_ID\"\n        \"GITHUB_SECRET\"\n        \"SMTP_HOST\"\n        \"SMTP_USER\"\n        \"SMTP_PASSWORD\"\n        \"SLACK_WEBHOOK_URL\"\n        \"WEBHOOK_URL\"\n        \"WEBHOOK_SECRET\"\n    )\n    \n    # Check required variables\n    for var in \"${required_vars[@]}\"; do\n        if [[ \" ${env_vars[*]} \" =~ \" ${var} \" ]]; then\n            if [[ -z \"${!var:-}\" ]]; then\n                missing_vars+=(\"$var\")\n            else\n                log_verbose \"Found required variable: $var\"\n            fi\n        fi\n    done\n    \n    # Check optional variables\n    for var in \"${optional_vars_list[@]}\"; do\n        if [[ \" ${env_vars[*]} \" =~ \" ${var} \" ]]; then\n            if [[ -z \"${!var:-}\" ]]; then\n                optional_vars+=(\"$var\")\n            else\n                log_verbose \"Found optional variable: $var\"\n            fi\n        fi\n    done\n    \n    # Report missing required variables\n    if [[ ${#missing_vars[@]} -gt 0 ]]; then\n        log_error \"Missing required environment variables:\"\n        printf '  %s\\n' \"${missing_vars[@]}\"\n        \n        if [[ \"$FIX_ISSUES\" == \"true\" ]]; then\n            log_info \"Use the secrets management script to set these variables\"\n        fi\n        \n        return 1\n    fi\n    \n    # Report missing optional variables\n    if [[ ${#optional_vars[@]} -gt 0 ]]; then\n        log_warning \"Missing optional environment variables:\"\n        printf '  %s\\n' \"${optional_vars[@]}\"\n        log_info \"These variables are optional but may be needed for full functionality\"\n    fi\n    \n    log_success \"Environment variables validation passed\"\n    return 0\n}\n"# Function
 to validate secrets configuration\nvalidate_secrets() {\n    local secrets_file=\"$1\"\n    \n    if [[ \"$CHECK_SECRETS\" != \"true\" ]]; then\n        log_info \"Skipping secrets validation\"\n        return 0\n    fi\n    \n    log_info \"Validating secrets configuration: $secrets_file\"\n    \n    if [[ ! -f \"$secrets_file\" ]]; then\n        log_error \"Secrets file not found: $secrets_file\"\n        return 1\n    fi\n    \n    # Validate YAML syntax\n    if ! validate_yaml_syntax \"$secrets_file\"; then\n        return 1\n    fi\n    \n    # Check for Supabase Vault references\n    if ! grep -q \"vault:\" \"$secrets_file\"; then\n        log_warning \"No Supabase Vault references found in secrets file\"\n        log_info \"Consider using Supabase Vault for secret management\"\n    else\n        log_verbose \"Found Supabase Vault references\"\n    fi\n    \n    # Check for hardcoded secrets (security issue)\n    local hardcoded_patterns=(\n        \"password.*:.*[a-zA-Z0-9]{8,}\"\n        \"secret.*:.*[a-zA-Z0-9]{16,}\"\n        \"key.*:.*[a-zA-Z0-9]{20,}\"\n        \"token.*:.*[a-zA-Z0-9]{20,}\"\n    )\n    \n    local security_issues=()\n    \n    for pattern in \"${hardcoded_patterns[@]}\"; do\n        if grep -qiE \"$pattern\" \"$secrets_file\"; then\n            security_issues+=(\"Potential hardcoded secret found (pattern: $pattern)\")\n        fi\n    done\n    \n    if [[ ${#security_issues[@]} -gt 0 ]]; then\n        log_error \"Security issues found in secrets file:\"\n        printf '  %s\\n' \"${security_issues[@]}\"\n        log_error \"Secrets should use Vault references, not hardcoded values\"\n        return 1\n    fi\n    \n    log_success \"Secrets validation passed\"\n    return 0\n}\n\n# Function to validate Supabase connectivity\nvalidate_supabase_connectivity() {\n    if [[ \"$CHECK_CONNECTIVITY\" != \"true\" ]]; then\n        log_info \"Skipping connectivity checks\"\n        return 0\n    fi\n    \n    log_info \"Validating Supabase connectivity...\"\n    \n    local supabase_url=\"${SUPABASE_URL:-}\"\n    local supabase_key=\"${SUPABASE_ANON_KEY:-}\"\n    \n    if [[ -z \"$supabase_url\" ]] || [[ -z \"$supabase_key\" ]]; then\n        log_warning \"Supabase credentials not available for connectivity test\"\n        return 0\n    fi\n    \n    # Test Supabase API connectivity\n    if ! curl -s --max-time 10 -H \"apikey: $supabase_key\" \"$supabase_url/rest/v1/\" > /dev/null; then\n        log_error \"Cannot connect to Supabase API: $supabase_url\"\n        return 1\n    fi\n    \n    log_success \"Supabase connectivity validated\"\n    return 0\n}\n\n# Function to validate database connectivity\nvalidate_database_connectivity() {\n    if [[ \"$CHECK_CONNECTIVITY\" != \"true\" ]]; then\n        return 0\n    fi\n    \n    log_info \"Validating database connectivity...\"\n    \n    local db_host=\"${DB_HOST:-localhost}\"\n    local db_port=\"${DB_PORT:-5432}\"\n    local db_name=\"${DB_NAME:-}\"\n    local db_user=\"${DB_USER:-}\"\n    local db_password=\"${DB_PASSWORD:-}\"\n    \n    if [[ -z \"$db_name\" ]] || [[ -z \"$db_user\" ]]; then\n        log_warning \"Database credentials not available for connectivity test\"\n        return 0\n    fi\n    \n    # Test database connectivity using psql if available\n    if command -v psql &> /dev/null; then\n        local db_url=\"postgresql://$db_user:$db_password@$db_host:$db_port/$db_name\"\n        \n        if ! PGPASSWORD=\"$db_password\" psql -h \"$db_host\" -p \"$db_port\" -U \"$db_user\" -d \"$db_name\" -c \"SELECT 1;\" &> /dev/null; then\n            log_error \"Cannot connect to database: $db_host:$db_port/$db_name\"\n            return 1\n        fi\n        \n        log_success \"Database connectivity validated\"\n    else\n        # Test basic network connectivity\n        if command -v nc &> /dev/null; then\n            if ! nc -z \"$db_host\" \"$db_port\" 2>/dev/null; then\n                log_error \"Cannot reach database host: $db_host:$db_port\"\n                return 1\n            fi\n            log_success \"Database host reachable\"\n        else\n            log_warning \"Cannot test database connectivity (psql and nc not available)\"\n        fi\n    fi\n    \n    return 0\n}\n\n# Function to validate Redis connectivity\nvalidate_redis_connectivity() {\n    if [[ \"$CHECK_CONNECTIVITY\" != \"true\" ]]; then\n        return 0\n    fi\n    \n    log_info \"Validating Redis connectivity...\"\n    \n    local redis_host=\"${REDIS_HOST:-localhost}\"\n    local redis_port=\"${REDIS_PORT:-6379}\"\n    local redis_password=\"${REDIS_PASSWORD:-}\"\n    \n    # Test Redis connectivity using redis-cli if available\n    if command -v redis-cli &> /dev/null; then\n        local redis_cmd=\"redis-cli -h $redis_host -p $redis_port\"\n        \n        if [[ -n \"$redis_password\" ]]; then\n            redis_cmd=\"$redis_cmd -a $redis_password\"\n        fi\n        \n        if ! $redis_cmd ping &> /dev/null; then\n            log_error \"Cannot connect to Redis: $redis_host:$redis_port\"\n            return 1\n        fi\n        \n        log_success \"Redis connectivity validated\"\n    else\n        # Test basic network connectivity\n        if command -v nc &> /dev/null; then\n            if ! nc -z \"$redis_host\" \"$redis_port\" 2>/dev/null; then\n                log_error \"Cannot reach Redis host: $redis_host:$redis_port\"\n                return 1\n            fi\n            log_success \"Redis host reachable\"\n        else\n            log_warning \"Cannot test Redis connectivity (redis-cli and nc not available)\"\n        fi\n    fi\n    \n    return 0\n}\n\n# Function to validate agent configuration\nvalidate_agent_config() {\n    local config_file=\"$1\"\n    \n    log_info \"Validating agent configuration...\"\n    \n    # Check if agents section exists and has valid structure\n    if command -v yq &> /dev/null; then\n        # Check max_concurrent is reasonable\n        local max_concurrent=$(yq eval '.agents.max_concurrent' \"$config_file\" 2>/dev/null || echo \"null\")\n        if [[ \"$max_concurrent\" != \"null\" ]] && [[ \"$max_concurrent\" -gt 10 ]]; then\n            log_warning \"High max_concurrent agents setting: $max_concurrent (consider reducing for resource management)\"\n        fi\n        \n        # Check if at least one agent is enabled\n        local enabled_agents=$(yq eval '.agents.available[] | select(.enabled == true) | .name' \"$config_file\" 2>/dev/null | wc -l || echo \"0\")\n        if [[ \"$enabled_agents\" -eq 0 ]]; then\n            log_error \"No agents are enabled in configuration\"\n            return 1\n        else\n            log_verbose \"Found $enabled_agents enabled agents\"\n        fi\n        \n        # Validate agent timeouts\n        local invalid_timeouts=$(yq eval '.agents.available[] | select(.timeout and (.timeout | test(\"^[0-9]+[smh]$\") | not)) | .name' \"$config_file\" 2>/dev/null || echo \"\")\n        if [[ -n \"$invalid_timeouts\" ]]; then\n            log_error \"Invalid timeout format for agents: $invalid_timeouts\"\n            log_error \"Timeout format should be like: 30s, 5m, 1h\"\n            return 1\n        fi\n    else\n        log_warning \"Cannot validate detailed agent configuration (yq not available)\"\n    fi\n    \n    log_success \"Agent configuration validation passed\"\n    return 0\n}\n\n# Main validation function\nmain_validation() {\n    log_info \"Starting configuration validation for environment: $ENVIRONMENT\"\n    \n    local env_dir=\"$ENVIRONMENTS_DIR/$ENVIRONMENT\"\n    local config_file=\"$env_dir/config.yaml\"\n    local secrets_file=\"$env_dir/secrets.yaml\"\n    \n    if [[ ! -d \"$env_dir\" ]]; then\n        log_error \"Environment directory not found: $env_dir\"\n        log_info \"Available environments:\"\n        ls -1 \"$ENVIRONMENTS_DIR\" 2>/dev/null || echo \"No environments found\"\n        exit 1\n    fi\n    \n    local validation_errors=0\n    \n    # Load environment-specific variables if .env file exists\n    local env_file=\"$env_dir/.env\"\n    if [[ -f \"$env_file\" ]]; then\n        log_verbose \"Loading environment variables from: $env_file\"\n        set -a\n        source \"$env_file\"\n        set +a\n    fi\n    \n    # Run all validations\n    if ! validate_config_structure \"$config_file\"; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_environment_variables \"$config_file\"; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_secrets \"$secrets_file\"; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_agent_config \"$config_file\"; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_supabase_connectivity; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_database_connectivity; then\n        ((validation_errors++))\n    fi\n    \n    if ! validate_redis_connectivity; then\n        ((validation_errors++))\n    fi\n    \n    # Summary\n    echo \"\"\n    log_info \"Configuration Validation Summary\"\n    echo \"===================================\"\n    echo \"Environment: $ENVIRONMENT\"\n    echo \"Config file: $config_file\"\n    echo \"Secrets file: $secrets_file\"\n    echo \"\"\n    \n    if [[ $validation_errors -eq 0 ]]; then\n        log_success \"All configuration validations passed! Environment is ready for deployment.\"\n        exit 0\n    else\n        log_error \"$validation_errors validation(s) failed. Please fix the issues above.\"\n        \n        if [[ \"$FIX_ISSUES\" == \"true\" ]]; then\n            log_info \"Some issues may have been automatically fixed. Please re-run validation.\"\n        else\n            log_info \"Use --fix flag to attempt automatic fixes for some issues.\"\n        fi\n        \n        exit 1\n    fi\n}\n\n# Parse command line arguments\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        --environment)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --verbose)\n            VERBOSE=true\n            shift\n            ;;\n        --fix)\n            FIX_ISSUES=true\n            shift\n            ;;\n        --skip-secrets)\n            CHECK_SECRETS=false\n            shift\n            ;;\n        --skip-connectivity)\n            CHECK_CONNECTIVITY=false\n            shift\n            ;;\n        --help|-h)\n            show_help\n            exit 0\n            ;;\n        *)\n            log_error \"Unknown option: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\ndone\n\n# Make script executable\nchmod +x \"$0\"\n\n# Run main validation\nmain_validation\n"